window.PAIRS=[{"n":3,"s":0.721,"o":{"i":"세무사2022_59-26-3","t":"해로운 외부성이 존재하면 해당 재화는 사회적 최적 수준보다 과다 생산되는 경향이 있다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2025_62-30-5","t":"이로운 외부성이 존재하면 해당재화의 생산량은 사회적 최적 수준보다 과다 생산되는 경향이 있다.","y":2025,"e":"세무사 1차"}},{"n":3,"s":0.483,"o":{"i":"세무사2024_61-30-4","t":"해당 권리가 누구에게 주어지든 울타리는 설치되지 않는다.","y":2024,"e":"세무사 1차"},"x":{"i":"세무사2024_61-30-3","t":"해당 권리가 누구에게 주어지든 울타리가 설치된다.","y":2024,"e":"세무사 1차"}},{"n":8,"s":0.792,"o":{"i":"세무사2022_59-18-2","t":"여가가 정상재일 경우, 누진소득세 부과가 노동공급에 미치는 영향은 비례소득세 부과와 유사하지만 고소득자에게 불리하다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2017_54-12-4","t":"여가가 정상재일 경우 누진소득세 부과가 노동공급에 미치는 영향은 비례소득세 부과와 유사하지만 고소득자에게 유리하다.","y":2017,"e":"세무사 1차"}},{"n":8,"s":0.784,"o":{"i":"세무사2022_59-18-4","t":"여가가 정상재일 경우, 임금변화에 따른 소득효과가 대체효과보다 크다면 후방굴절형 노동공급곡선이 될 것이다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2017_54-12-1","t":"여가가 정상재일 경우 임금변화에 따른 소득효과가 대체효과보다 작다면 후방굴절형 노동공급곡선이 될 것이다.","y":2017,"e":"세무사 1차"}},{"n":8,"s":0.702,"o":{"i":"세무사2016_53-25-3","t":"위험부담 행위의 소득탄력성이 양이면, 소득효과와 대체효과 모두 위험자산에 대한 투자를 줄인다.","y":2016,"e":"세무사 1차"},"x":{"i":"세무사2016_53-25-2","t":"위험부담 행위의 소득탄력성이 음이면, 소득효과와 대체효과 모두 위험자산에 대한 투자를 늘린다.","y":2016,"e":"세무사 1차"}},{"n":8,"s":0.701,"o":{"i":"세무사2022_59-19-5","t":"자기자본의 귀속이자비용과 차입금에 대한 이자공제가 허용되고 세법상 감가상각률과 경제적 감가상각률이 일치할 경우 법인세는 투자에 영향을 미치지 않는다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2021_58-14-5","t":"자기자본의 귀속이자비용이 공제되지 않아도, 차입금에 대한 이자공제가 허용되고 세법상 감가상각률과 경제적 감가상각률이 일치하면 법인세는 투자에 영향을 미치지 않는다.","y":2021,"e":"세무사 1차"}},{"n":5,"s":0.8,"o":{"i":"세무사2025_62-32-4","t":"시장이자율이 사회적 할인율보다 높을 때 시장이자율을 할인율로 사용하면 공공사업의 경제성은 낮아질 수 있다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2023_60-39-4","t":"시장이자율이 사회적 할인율보다 높을 때 시장이자율을 할인율로 사용하면 공공사업의 경제성이 커질 수 있다.","y":2023,"e":"세무사 1차"}},{"n":5,"s":0.431,"o":{"i":"세무사2025_62-31-3","t":"독점자가 생산한 상품을 구입하였으나 그 상품의 생산량이 불변이면 시장가격을 평가 기준으로 한다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2025_62-31-2","t":"독점자가 생산한 상품을 구입하여 그 상품의 생산량이 그만큼 증가하였다면 평균비용을 평가기준으로 한다.","y":2025,"e":"세무사 1차"}},{"n":11,"s":0.421,"o":{"i":"세무사2016_53-06-2","t":"조세부담-편익 연계가 강한 공공재는 지방정부가, 그렇지 않은 공공재는 중앙 정부가 공급하는 것이 바람직하다.","y":2016,"e":"세무사 1차"},"x":{"i":"세무사2016_53-06-5","t":"부정적 외부성이 존재하는 공공재는 중앙정부가, 긍정적 외부성이 존재하는 공공재는 지방정부가 공급하는 것이 바람직하다.","y":2016,"e":"세무사 1차"}},{"n":2,"s":0.478,"o":{"i":"세무사2022_59-27-3","t":"공공재의 최적 공급수준은 개별 이용자의 한계편익의 합과 한계비용이 일치할 때 달성된다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2016_53-32-4","t":"파레토 효율은 공공재 개별 이용자의 한계편익과 한계비용이 일치할 때 달성된다.","y":2016,"e":"세무사 1차"}},{"n":2,"s":0.434,"o":{"i":"세무사2021_58-20-4","t":"규모의 경제가 존재하는 경우 한계비용과 일치하는 수준에서 가격이 설정되면 효율적인 배분을 달성할 수 있다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2021_58-20-2","t":"외부성이 존재하는 경우 한계비용과 일치하는 수준에서 가격이 설정되어야 한다.","y":2021,"e":"세무사 1차"}},{"n":7,"s":0.615,"o":{"i":"세무사2024_61-03-1","t":"수요의 가격탄력성이 클수록 초과부담은 커진다.","y":2024,"e":"세무사 1차"},"x":{"i":"세무사2023_60-02-4","t":"수요의 가격탄력성이 클수록 초과부담은 오히려 작아진다.","y":2023,"e":"세무사 1차"}},{"n":10,"s":0.7,"o":{"i":"세무사2024_61-24-4","t":"[수식] 이면, 현금으로 받을 때 반드시 더 높은 효용을 얻는다.","y":2024,"e":"세무사 1차"},"x":{"i":"세무사2024_61-24-5","t":"[수식] 이면, 상품권으로 받을 때 반드시 더 높은 효용을 얻는다.","y":2024,"e":"세무사 1차"}},{"n":10,"s":0.6,"o":{"i":"세무사2021_58-38-5","t":"효용함수는 소득의 한계효용이 체감한다는 가정이 필요하다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2025_62-39-3","t":"효용함수는 소득의 한계효용이 불변이라는 가정이 필요하다.","y":2025,"e":"세무사 1차"}},{"n":10,"s":0.597,"o":{"i":"세무사2021_58-33-2","t":"달튼(H. Dalton)의 평등지수: 0과 1 사이의 값을 가지며, 1에 가까울수록 소득이 평등하게 분배되었음을 나타낸다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2021_58-33-1","t":"지니(Gini)계수: 0과 1 사이의 값을 가지며, 1에 가까울수록 소득이 평등하게 분배되었음을 나타낸다.","y":2021,"e":"세무사 1차"}},{"n":10,"s":0.553,"o":{"i":"세무사2026_63-34-5","t":"암묵적 한계세율이 영(0)인 구간에서는 대체효과가 발생하지 않는다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2024_61-35-5","t":"암묵적 한계세율이 영(0)인 구간에서는 대체효과가 소득효과보다 크다.","y":2024,"e":"세무사 1차"}},{"n":1,"s":0.581,"o":{"i":"세무사2022_59-23-5","t":"자연독점기업에 대한 한계비용가격설정은 독점으로 인한 비효율성을 제거할 수 있다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2025_62-23-3","t":"비용체감산업에 대한 평균비용 가격설정은 독점으로 인한 비효율성을 제거할 수 있다.","y":2025,"e":"세무사 1차"}},{"n":1,"s":0.561,"o":{"i":"세무사2021_58-24-4","t":"공리주의 사회후생함수에 의하면 사회후생의 극대화를 위해서는 각 개인소득의 한계 효용이 같아야 한다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2025_62-26-5","t":"공리주의적 사회후생함수에 의하면 소득의 한계효용이 감소할 때 사회후생의 극대화를 위해서는 각 개인소득의 한계효용이 서로 달라야 한다.","y":2025,"e":"세무사 1차"}},{"n":1,"s":0.432,"o":{"i":"세무사2025_62-26-2","t":"공리주의적 사회후생함수는 모든 구성원에게 동일한 가중치를 평등하게 부여한다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2022_59-22-5","t":"평등주의적 사회후생함수는 사회 구성원들에게 동일한 가중치를 부여한다.","y":2022,"e":"세무사 1차"}},{"n":1,"s":0.383,"o":{"i":"세무사2025_62-23-5","t":"국민연금의 강제 가입은 늦게 은퇴할 가능성이 높은 근로자들의 가입을 유도하여 역선택 문제를 해결할 수 있다.","y":2025,"e":"세무사 1차"},"x":{"i":"세무사2022_59-23-1","t":"국민연금의 강제 가입은 일찍 은퇴할 가능성이 높은 사람만 가입하는 역선택 문제를 해결할 수 없다.","y":2022,"e":"세무사 1차"}},{"n":6,"s":0.696,"o":{"i":"세무사2021_58-08-5","t":"소비자에게 귀착되는 종량세 부담은 800이다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2022_59-15-3","t":"소비자에게 귀착되는 종량세 부담은 1200이다.","y":2022,"e":"세무사 1차"}},{"n":6,"s":0.565,"o":{"i":"세무사2022_59-15-2","t":"종량세 과세에 따른 초과부담은 450이다.","y":2022,"e":"세무사 1차"},"x":{"i":"세무사2021_58-08-2","t":"종량세 과세에 따른 초과부담은 1,200이다.","y":2021,"e":"세무사 1차"}},{"n":6,"s":0.453,"o":{"i":"세무사2016_53-26-3","t":"독점시장에서 소비자에게 과세하는 경우 종가세와 종량세가 생산량에 동일하게 영향을 미친다면, 종가세의 조세수입이 종량세의 조세수입보다 많아진다.","y":2016,"e":"세무사 1차"},"x":{"i":"세무사2016_53-26-4","t":"독점시장에서 소비자에게 과세하는 경우 종가세와 종량세로 인한 조세수입이 같다면, 종가세의 생산량보다 종량세의 생산량이 더 많아진다.","y":2016,"e":"세무사 1차"}},{"n":6,"s":0.3,"o":{"i":"세무사2021_58-04-1","t":"소득의 한계효용이 감소하고 직선이다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2021_58-04-4","t":"소득의 한계효용이 일정하다.","y":2021,"e":"세무사 1차"}},{"n":12,"s":0.59,"o":{"i":"세무사2024_61-39-1","t":"보몰효과(Baumol effect)에 의하면 정부가 생산ㆍ공급하는 서비스의 생산비용이 상대적으로 빠르게 증가하여 정부지출이 늘어나게 된다.","y":2024,"e":"세무사 1차"},"x":{"i":"세무사2023_60-38-2","t":"보몰효과(Baumol effect)에 의하면, 정부가 생산·공급하는 서비스의 생산비용이 상대적으로 낮아지면 정부지출이 증가하게 된다.","y":2023,"e":"세무사 1차"}},{"n":12,"s":0.5,"o":{"i":"세무사2026_63-39-4","t":"브라운-잭슨(C. Brown and P. Jackson)에 의하면, 중위투표자의 공공서비스에 대한 소득 탄력성이 충분히 크면 정부지출의 상대적 비중이 점차 커진다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2023_60-38-5","t":"브라운-잭슨(C. Brown & P. Jackson)에 의하면, 중위투표자의 공공서비스에 대한 수요의 소득탄력성이 줄어들게 되면 정부지출의 비중이 증가하게 된다.","y":2023,"e":"세무사 1차"}},{"n":12,"s":0.353,"o":{"i":"세무사2021_58-35-2","t":"소비 지출이 증가하므로 총수요 곡선이 오른쪽으로 이동한다.","y":2021,"e":"세무사 1차"},"x":{"i":"세무사2025_62-20-2","t":"소비 지출이 감소하여 총수요 곡선이 좌측으로 이동한다.","y":2025,"e":"세무사 1차"}},{"n":4,"s":0.56,"o":{"i":"세무사2026_63-28-3","t":"꽁도세 승자는 [수식], 보다 승자는 [수식] 이다.","y":2026,"e":"세무사 1차"},"x":{"i":"세무사2026_63-28-5","t":"꽁도세 승자는 존재하지 않지만, 보다 승자는 [수식] 이다.","y":2026,"e":"세무사 1차"}}];
